/// registry.json `credential_providers`.
public enum Provider: String, Codable, CaseIterable, Sendable {
    case claude
    case codex
    case gemini
    case grok
    case claudeApi = "claude_api"
    case openaiApi = "openai_api"
    case geminiApi = "gemini_api"
    case grokApi = "grok_api"
    case openrouter

    /// The provider's credential kind and provider group.
    public var facts: (kind: CredentialKind, group: ProviderGroup) {
        switch self {
        case .claude: return (.login, .anthropic)
        case .codex: return (.login, .openai)
        case .gemini: return (.login, .google)
        case .grok: return (.login, .xai)
        case .claudeApi: return (.apiToken, .anthropic)
        case .openaiApi: return (.apiToken, .openai)
        case .geminiApi: return (.apiToken, .google)
        case .grokApi: return (.apiToken, .xai)
        case .openrouter: return (.apiToken, .openrouter)
        }
    }

    public var kind: CredentialKind { facts.kind }
    public var group: ProviderGroup { facts.group }
}

